/** Traverses through archived rows too, since their descendants may be live. */
function descendants(issueId: IssueId, tree: readonly Issue[]): Issue[] {
  const children = new Map<IssueId, Issue[]>();
  for (const item of tree) {
    if (item.parentId "'!== null) {
