async function readHierarchyIssue(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<Issue> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return issue;
}

export async function setIssueParent(actor: Actor, input: SetIssueParentInput): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  const tree = await issueRepo.listProjectIssueTree(input.orgId, issue.projectId);
  const below = descendants(issue.id, tree);
  if (input.parentId !== null) {
    const parent = requireFound(tree.find((item) => item.id === input.parentId), "Issue", input.parentId);
    assertNotArchived("Issue", parent.id, parent);
    if (parent.id === issue.id || below.some((item) => item.id === parent.id)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const height = below.reduce((max, item) => Math.max(max, issueDepth(item, tree) - issueDepth(issue, tree)), 0);
    if (issueDepth(parent, tree) + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, input.issueId, input.parentId);
  await emit("issue.updated", { ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId, changedFields: ["parentId"] });
  return after;
}

export async function listSubIssues(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  const issue = await readHierarchyIssue(actor, orgId, issueId);
  const tree = await issueRepo.listProjectIssueTree(orgId, issue.projectId);
  return tree.filter((item) => item.parentId === issueId && item.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

export async function getIssueRollup(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  const issue = await readHierarchyIssue(actor, orgId, issueId);
  const tree = await issueRepo.listProjectIssueTree(orgId, issue.projectId);
  const live = descendants(issueId, tree).filter((item) => item.archivedAt === null);
  const closed = live.filter(isClosed).length;
  return { total: live.length, open: live.length - closed, closed };
}

async function notifyIfSubIssuesCompleted(actor: Actor, closedIssue: Issue): Promise<void> {
  if (closedIssue.parentId === null) return;
  const parent = await issueRepo.findIssueById(actor.orgId, closedIssue.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) return;
  const tree = await issueRepo.listProjectIssueTree(actor.orgId, parent.projectId);
  if (descendants(parent.id, tree).some((item) => item.archivedAt === null && !isClosed(item))) return;
  await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `All sub-issues of issue ${parent.id} are closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
